import { createHash } from 'node:crypto';

/**
 * Stored representation of an employee web session.
 *
 * SENSITIVITY NOTE:
 * Raw session tokens are high-entropy bearer secrets generated by the caller.
 * The persistence layer stores ONLY the cryptographic SHA-256 digest (`sessionTokenHash`).
 * The raw token is NEVER stored in PostgreSQL or logged.
 */
export interface UserSessionRecord {
  readonly id: string;
  readonly userId: string;
  readonly sessionTokenHash: string;
  readonly ipAddress: string | null;
  readonly userAgent: string | null;
  readonly createdAt: Date;
  readonly lastActiveAt: Date;
  readonly expiresAt: Date;
  readonly revokedAt: Date | null;
}

/**
 * Computes the authoritative SHA-256 digest of a raw high-entropy session token.
 *
 * INVARIANT:
 * Raw session tokens must be generated using a cryptographically secure random source
 * (e.g., `crypto.randomBytes(32).toString('hex')`).
 * Do not derive session tokens from passwords or predictable seeds.
 */
export function hashSessionToken(rawToken: string): string {
  if (!rawToken || typeof rawToken !== 'string') {
    throw new Error('Invalid raw session token: must be a non-empty string');
  }
  return createHash('sha256').update(rawToken, 'utf8').digest('hex');
}

/**
 * Checks whether a session record is currently active (neither expired nor revoked).
 */
export function isSessionActive(session: UserSessionRecord, now: Date): boolean {
  if (session.revokedAt !== null) {
    return false;
  }
  return session.expiresAt.getTime() > now.getTime();
}
